<script setup lang="ts">
import { computed } from 'vue';

const props = defineProps<{
  category: string;
  label: string;
}>();

const icon = computed(() => {
  const label = props.label.toLocaleLowerCase();
  if (props.category === 'devices') {
    if (label === 'desktop') return 'desktop';
    if (label === 'mobile') return 'mobile';
    if (label === 'tablet') return 'tablet';
    return 'other';
  }
  if (props.category === 'browsers') {
    if (label === 'chrome') return 'chrome';
    if (label === 'edge') return 'edge';
    if (label === 'safari') return 'safari';
    if (label === 'opera') return 'opera';
    if (label === 'firefox') return 'firefox';
    return 'other';
  }
  if (props.category === 'operating-systems') {
    if (label === 'windows') return 'windows';
    if (label === 'linux') return 'linux';
    if (label === 'macos') return 'macos';
    if (label === 'android') return 'android';
    if (label === 'ios') return 'ios';
    return 'other';
  }
  return 'language';
});
</script>

